fun fetchWithRetry(): Flow<List<Item>> =
    flow { emit(api.fetch()) }
        .retryWhen { cause, attempt ->
            val transient = cause is IOException || cause is HttpException && cause.code() in 500..599
            if (transient && attempt < 3) {
                delay(1000L * (1 shl attempt) + Random.nextLong(0, 500))
                true
            } else false
        }

