// Listener wrapper: awaitClose is mandatory
fun locationFlow(): Flow<Location> = callbackFlow {
    val listener = LocationListener { loc -> trySend(loc) }
    locationManager.requestLocationUpdates(provider, 0L, 0f, listener)
    awaitClose { locationManager.removeUpdates(listener) }   // REQUIRED
}

fun locationFlow(): Flow<Location> =
    callbackFlow(capacity = Channel.BUFFERED) {
        val listener = LocationListener { loc ->
            val ok = trySend(loc).isSuccess   // check the drop
            if (!ok) log("location dropped")
        }
        locationManager.requestLocationUpdates(provider, 0L, 0f, listener)
        awaitClose { locationManager.removeUpdates(listener) }
    }

